 if kind in ('studio','lighting','audio'):
  s='<rect x="15" y="12" width="85" height="22" rx="5" fill="#bae6fd"/>'+text(57,27,c['studio'][0])+'<path d="M100 35L190 80L130 85Z" fill="#38bdf8" opacity=".2"/><circle cx="192" cy="69" r="15" fill="#8b5cf6"/><rect x="180" y="95" width="26" height="32" rx="5" fill="#111d35"/><rect x="290" y="45" width="12" height="60" rx="4" fill="#fff" stroke="#2563eb"/>'+text(192,48,c['studio'][1])+text(232,120,c['studio'][2])+text(302,30,c['studio'][3])+'<path d="M192 93V88" stroke="#2563eb" stroke-width="3"/><path d="M120 8H320" stroke="#b6c6dd" stroke-dasharray="5 4"/>'+text(230,18,c['studio'][4])
 elif kind in ('product','comparison'):
  s='<rect x="22" y="26" width="130" height="90" rx="10" fill="#d3dce9"/><rect x="193" y="26" width="130" height="90" rx="10" fill="#eff6ff" stroke="#2563eb"/><ellipse cx="90" cy="100" rx="32" ry="9" fill="#8497b4"/><ellipse cx="258" cy="100" rx="28" ry="7" fill="#c6dafa"/>'
  for x in (67,235):s+=f'<rect x="{x}" y="47" width="44" height="51" rx="8" fill="#38bdf8"/><rect x="{x+10}" y="37" width="24" height="13" rx="3" fill="#111d35"/>'
  s+=text(87,16,c['comparison'][0])+text(258,16,c['comparison'][1])
 else:
  s=''
  names=c['budget'] if kind=='budget' else c['workflow']
  for i,label in enumerate(names):
   x=5+i*(340/len(names));w=320/len(names)-5
   s+=f'<rect x="{x}" y="45" width="{w}" height="42" rx="8" fill="'+['#dbeafe','#bae6fd','#e0d7ff','#dbeafe'][i]+'"/>'+text(x+w/2,70,label)
 return '<div class="art"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 350 135">'+s+'</svg><div class="fine">'+' · '.join(str(i+1)+' '+e(label) for i,label in enumerate(labels))+'</div></div>'
