  if last and ch==7:
   for start in range(0,len(m.prompts),2):
    body='<p class="eyebrow">07 / '+c['chapters'][6]+'</p><h2>'+c['prompts']+'</h2><p class="fine">'+c['promptRule']+'</p>'
    for i,p in enumerate(m.prompts[start:start+2],start):body+=f'<div class="prompt"><h3>{i+1:02d} / {e(p["title"][lang])}</h3><p class="task">{e(p["task"][lang])}</p><p class="fine">{c["promptExample"]}: {e(p["example"][lang])}</p><p class="fine">{c["promptCheck"]}</p></div>'
